<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Application setup</title><style>*{box-sizing:border-box}body{margin:0;background:#f2f4f7;color:#101828;font-family:Arial,sans-serif}.page{min-height:100vh;padding:30px 16px}.box{max-width:760px;margin:auto}.head{text-align:center;margin-bottom:24px}.head h1{font-size:24px;margin:0 0 7px}.head p{color:#667085;font-size:13px;margin:0}.steps{display:flex;justify-content:center;align-items:center;margin-bottom:24px}.step{display:flex;align-items:center;gap:7px;color:#98a2b3;font-size:11px;font-weight:700}.step b{width:30px;height:30px;border-radius:50%;display:grid;place-items:center;background:#e4e7ec;color:#667085}.step.active{color:#175cd3}.step.active b{background:#175cd3;color:#fff}.line{width:70px;height:2px;background:#d0d5dd;margin:0 9px}.line.done{background:#12b76a}.card{background:#fff;border:1px solid #e4e7ec;border-radius:15px;box-shadow:0 12px 30px #1018280b;overflow:hidden}.title{padding:26px 30px;border-bottom:1px solid #eaecf0;background:#f8fbff}.eyebrow{font-size:10px;color:#175cd3;font-weight:800;letter-spacing:.1em;text-transform:uppercase}.title h2{font-size:21px;margin:9px 0 6px}.title p{font-size:12px;color:#667085;margin:0}.form{padding:28px 30px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:19px}.field.full{grid-column:1/-1}.field label{display:block;font-size:12px;font-weight:800;margin-bottom:7px}.req{color:#d92d20}.field input{width:100%;height:44px;padding:0 12px;border:1px solid #d0d5dd;border-radius:8px;font-size:13px;outline:0}.field input:focus{border-color:#175cd3;box-shadow:0 0 0 4px #175cd31a}.help{display:block;color:#98a2b3;font-size:10px;margin-top:5px}.error{color:#b42318;font-size:11px;margin-top:5px}.notice{margin-top:22px;padding:12px 14px;border-radius:8px;background:#f9fafb;border:1px solid #eaecf0;color:#667085;font-size:11px;line-height:1.5}.actions{display:flex;justify-content:space-b